import{_ as t,o,c as a,a2 as d}from"./chunks/framework.DoCD98hS.js";const b=JSON.parse('{"title":"Fantastic Mobile · Fm 组件、基础库与 H5 模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/fanh5.md","filePath":"modules/catalog/fanh5.md","lastUpdated":1795479113000}'),c={name:"modules/catalog/fanh5.md"};function r(l,e,h,n,i,s){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="fantastic-mobile-·-fm-组件、基础库与-h5-模板" tabindex="-1">Fantastic Mobile · Fm 组件、基础库与 H5 模板 <a class="header-anchor" href="#fantastic-mobile-·-fm-组件、基础库与-h5-模板" aria-label="Permalink to &quot;Fantastic Mobile · Fm 组件、基础库与 H5 模板&quot;">​</a></h1><p>将 Fantastic Mobile 的 libs、comps 和 Vant + UnoCSS H5 模板集中介绍，公共接入步骤只维护一份。</p><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/libs-fanh5</code></td><td>设置项、主题变量、版权插件等普通基础库</td></tr><tr><td><code>@melt-js/comps-fanh5</code></td><td>Fm 系列移动端远程组件、四个 <code>useFm*</code> hooks 与 resolver</td></tr><tr><td><code>@melt-js/tpl-vue3-h5-vite-vant-unocss-forever-fanh5</code></td><td>Vue 3 + Vant + UnoCSS 的 H5 示例宿主</td></tr></tbody></table><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>演示地址</th></tr></thead><tbody><tr><td><code>tpl-vue3-h5-vite-vant-unocss-forever-fanh5</code></td><td><a href="https://unpkg.com/@melt-js/tpl-vue3-h5-vite-vant-unocss-forever-fanh5/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr></tbody></table><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td>libs：设置项、主题表、版权插件</td><td>通过公开子路径组织</td></tr><tr><td>comps：<code>useFmToast</code> / <code>useFmDrawer</code> / <code>useFmModal</code> / <code>useFmLoading</code></td><td>消息、抽屉、弹层与加载 hooks</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td><code>FmButton</code> / <code>FmButtonGroup</code> / <code>FmInput</code> / <code>FmSelect</code> / <code>FmCheckbox</code> / <code>FmRadioGroup</code> / <code>FmSwitch</code> / <code>FmSlider</code></td><td>表单与基础交互</td></tr><tr><td><code>FmCard</code> / <code>FmTabs</code> / <code>FmDrawer</code> / <code>FmModal</code> / <code>FmToast</code> / <code>FmLoading</code> / <code>FmScrollArea</code></td><td>布局、弹层与反馈</td></tr><tr><td><code>FmAlert</code> / <code>FmAvatar</code> / <code>FmBadge</code> / <code>FmDivider</code> / <code>FmLabel</code> / <code>FmIcon</code> / <code>FmPageMain</code> / <code>FmTrend</code></td><td>展示与信息呈现</td></tr></tbody></table><h2 id="接入方式" tabindex="-1">接入方式 <a class="header-anchor" href="#接入方式" aria-label="Permalink to &quot;接入方式&quot;">​</a></h2><p><code>libs-fanh5</code> 按普通依赖使用，<code>comps-fanh5</code> 预加载后从包根具名使用；自动导入由包内 resolver 完成，组件前缀为 <code>Fm</code>。</p><h2 id="模板简介" tabindex="-1">模板简介 <a class="header-anchor" href="#模板简介" aria-label="Permalink to &quot;模板简介&quot;">​</a></h2><p>模板属 Fantastic Mobile 体系，公共基础能力归 <code>libs-fanh5</code>、公共 Fm 组件归 <code>comps-fanh5</code>，页面与业务编排保留在模板。技术栈为 Vue 3 · Vant 4 · UnoCSS · Pinia · VueUse · Vue Router。</p><h2 id="从原开源模板快速接入" tabindex="-1">从原开源模板快速接入 <a class="header-anchor" href="#从原开源模板快速接入" aria-label="Permalink to &quot;从原开源模板快速接入&quot;">​</a></h2><ol><li>将原分散基础模块引用改为 <code>libs-fanh5</code> 的公开子路径，公共 Fm 组件改为 <code>comps-fanh5</code>。</li><li>main 共享 Vue、设置宿主主题并预加载组件，再动态进入 loadApp。</li><li>loadApp 注册全局 Fm 组件并完成应用、路由初始化；自动导入 hooks 指向包根。</li><li>保留模板 loading，等待 ready。</li></ol>',16)])])}const u=t(c,[["render",r]]);export{b as __pageData,u as default};
